INSERT INTO public.specialties (slug, name, h1_title, meta_title, meta_description, intro, body, tile_color, sort_order, is_active) VALUES
('hirurgiya','Хирургия','Хирургия в Бишкеке','Хирургия в клинике «Авиценна» — Бишкек','Плановые и малоинвазивные операции, консультация хирурга, перевязки и наблюдение в стационаре.','Плановые и экстренные операции, малоинвазивная хирургия, наблюдение в стационаре и полное сопровождение до выздоровления.','Опытные хирурги проводят консультации, амбулаторные вмешательства и плановые операции. Современная операционная, собственная лаборатория и стационар позволяют пройти весь путь — от обследования до реабилитации — в одной клинике.','bg-tile-mint',10,true),
('travmpunkt','Травмпункт 24/7','Круглосуточный травмпункт','Травмпункт 24/7 в Бишкеке — клиника «Авиценна»','Круглосуточная травматологическая помощь: рентген, гипс, обработка ран, консультация травматолога без записи.','Помощь при травмах круглосуточно и без записи: рентген, гипсование, обработка ран, консультация травматолога.','Ушибы, переломы, вывихи, растяжения и раны — принимаем в любое время суток. Рентген и осмотр травматолога выполняются сразу, при необходимости пациента госпитализируют в стационар клиники.','bg-tile-peach',20,true),
('statsionar','Стационар','Стационар клиники «Авиценна»','Стационар в Бишкеке — клиника «Авиценна»','Комфортные палаты, круглосуточное наблюдение врача и медсестёр, послеоперационный уход и капельницы.','Комфортные палаты, круглосуточное наблюдение врачей и медсестёр, послеоперационный уход и лечение под контролем.','Стационар рассчитан на плановое и послеоперационное лечение. Палаты с санузлом, питание, ежедневный обход врача, капельницы и процедуры по назначению, при необходимости — консультации смежных специалистов.','bg-tile-lilac',30,true),
('kardiolog','Кардиология','Кардиолог в Бишкеке','Кардиолог в клинике «Авиценна» — Бишкек','Приём кардиолога, ЭКГ, ЭхоКГ, холтер и подбор терапии при гипертонии и аритмии.','Диагностика и лечение болезней сердца и сосудов: ЭКГ, ЭхоКГ, холтер, подбор терапии.','Кардиологи ведут пациентов с гипертонией, аритмией, ишемической болезнью и сердечной недостаточностью. Обследование проводится в день обращения, по результатам врач составляет схему лечения и план наблюдения.','bg-tile-mint',40,true),
('nevrolog','Неврология','Невролог в Бишкеке','Невролог в клинике «Авиценна» — Бишкек','Лечение головных болей, боли в спине, головокружения и нарушений сна. Приём невролога и диагностика.','Головные боли, боли в спине и шее, головокружение, бессонница — помощь невролога и полное обследование.','Невролог выявляет причину симптомов: осмотр, УЗИ сосудов, лабораторные анализы и при необходимости консультации смежных специалистов. Назначаем медикаментозное лечение, физиотерапию и реабилитацию.','bg-tile-lilac',50,true),
('ginekolog','Гинекология','Гинеколог в Бишкеке','Гинеколог в клинике «Авиценна» — Бишкек','Приём гинеколога, УЗИ, анализы, ведение беременности и лечение воспалительных заболеваний.','Профилактические осмотры, УЗИ, лечение воспалений, ведение беременности и деликатный подход.','Гинекологи клиники ведут пациенток любого возраста: профосмотр и кольпоскопия, лечение инфекций и нарушений цикла, подбор контрацепции, наблюдение беременности с УЗИ и анализами на месте.','bg-tile-peach',60,true),
('pediatr','Педиатрия','Педиатр в Бишкеке','Педиатр в клинике «Авиценна» — Бишкек','Приём педиатра, профилактические осмотры, справки, вакцинация и лечение детских заболеваний.','Наблюдение здоровья ребёнка: профосмотры, справки, анализы и лечение детских заболеваний.','Педиатры принимают детей с рождения: плановые осмотры, оценка развития, лечение ОРВИ и хронических состояний, оформление справок в сад и школу, консультации детских специалистов.','bg-tile-mint',70,true),
('gastroenterolog','Гастроэнтерология','Гастроэнтеролог в Бишкеке','Гастроэнтеролог в клинике «Авиценна» — Бишкек','Лечение гастрита, изжоги, болей в животе и заболеваний печени. УЗИ и анализы в клинике.','Гастрит, изжога, боли в животе, заболевания печени и желчного пузыря — диагностика и лечение.','Гастроэнтеролог назначает УЗИ органов брюшной полости, лабораторные исследования и подбирает схему лечения с рекомендациями по питанию. Контрольные приёмы помогают закрепить результат.','bg-tile-peach',80,true),
('endokrinolog','Эндокринология','Эндокринолог в Бишкеке','Эндокринолог в клинике «Авиценна» — Бишкек','Диабет, щитовидная железа, гормональные нарушения и лишний вес — приём эндокринолога и анализы.','Сахарный диабет, щитовидная железа, гормональные нарушения и контроль веса.','Эндокринолог проводит обследование гормонального фона, УЗИ щитовидной железы и подбирает терапию. Пациентам с диабетом составляем план контроля сахара, питания и регулярного наблюдения.','bg-tile-lilac',90,true)
